import { and, desc, eq, gt, like, ne, or } from "drizzle-orm";
import { drizzle } from "drizzle-orm/mysql2";
import { academicProfiles, competitionCertificates, competitionEnrollments, competitionSubmissionAttachments, competitionSubmissions, competitions, communities, communityMembers, conversationMembers, conversations, deviceNotificationSettings, InsertUser, learningResources, messages, notifications, ownerAuditLogs, postComments, postLikes, posts, postSaves, postShares, profileSubjects, profiles, progressReportGrants, resourceProgress, resourceSaves, safetyReports, studentBadges, studyGroupMembers, studyGroups, studyPlans, teacherMessages, teacherSessions, userPreferences, users, weeklyChallengeAwards, weeklyChallengeParticipants, weeklyChallenges } from "../drizzle/schema";
let _db: ReturnType<typeof drizzle> | null = null;
export async function getDb() { if (!_db && process.env.DATABASE_URL) _db = drizzle(process.env.DATABASE_URL); return _db; }
export async function upsertUser(user: InsertUser) { const db = await getDb(); if (!db) return; const isBootstrapOwner = Boolean(process.env.BOOTSTRAP_OWNER_EMAIL && user.email && process.env.BOOTSTRAP_OWNER_EMAIL.toLowerCase() === user.email.toLowerCase()); const values: InsertUser = { openId: user.openId, name: user.name ?? null, email: user.email ?? null, loginMethod: user.loginMethod ?? null, role: isBootstrapOwner ? "admin" : user.role ?? "user", lastSignedIn: user.lastSignedIn ?? new Date() }; await db.insert(users).values(values).onDuplicateKeyUpdate({ set: { name: values.name, email: values.email, loginMethod: values.loginMethod, lastSignedIn: values.lastSignedIn, ...(isBootstrapOwner ? { role: "admin" as const } : {}) } }); }
export async function getUserByOpenId(openId: string) { const db = await getDb(); if (!db) return undefined; return (await db.select().from(users).where(eq(users.openId, openId)).limit(1))[0]; }
export type PersonalProfileInput = { fullName: string; dateOfBirth: string; province: string; avatarUrl?: string | null }; export type AcademicProfileInput = { educationLevel: string; classYear: string; course: string; institution: string; subjects: string[] };
export async function getStudentProfile(userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível. Tente novamente em instantes."); const [profile] = await db.select().from(profiles).where(eq(profiles.userId, userId)).limit(1); if (!profile) return null; const [academic] = await db.select().from(academicProfiles).where(eq(academicProfiles.userId, userId)).limit(1); const selected = await db.select().from(profileSubjects).where(eq(profileSubjects.userId, userId)); const [preferences] = await db.select().from(userPreferences).where(eq(userPreferences.userId, userId)).limit(1); return { ...profile, academic: academic ?? null, subjects: selected.map((item) => item.subjectName), preferences: preferences ?? null }; }
export async function savePersonalProfile(userId: number, input: PersonalProfileInput) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível. Tente novamente em instantes."); await db.insert(profiles).values({ userId, ...input, avatarUrl: input.avatarUrl ?? null, isOnboardingComplete: false }).onDuplicateKeyUpdate({ set: { fullName: input.fullName, dateOfBirth: input.dateOfBirth, province: input.province, avatarUrl: input.avatarUrl ?? null } }); return getStudentProfile(userId); }
export async function saveAcademicProfile(userId: number, input: AcademicProfileInput) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível. Tente novamente em instantes."); const [profile] = await db.select().from(profiles).where(eq(profiles.userId, userId)).limit(1); if (!profile) throw new Error("Conclua primeiro os seus dados pessoais."); await db.insert(academicProfiles).values({ userId, educationLevel: input.educationLevel, classYear: input.classYear, course: input.course, institution: input.institution }).onDuplicateKeyUpdate({ set: { educationLevel: input.educationLevel, classYear: input.classYear, course: input.course, institution: input.institution } }); await db.delete(profileSubjects).where(eq(profileSubjects.userId, userId)); if (input.subjects.length) await db.insert(profileSubjects).values(input.subjects.map((subjectName) => ({ userId, subjectName }))); await db.insert(userPreferences).values({ userId }).onDuplicateKeyUpdate({ set: {} }); await db.update(profiles).set({ isOnboardingComplete: true }).where(eq(profiles.userId, userId)); return getStudentProfile(userId); }
export type CreatePostInput = { type: "text" | "photo" | "video" | "question" | "document"; body: string; mediaUrl?: string | null; mediaName?: string | null; mediaMimeType?: string | null };
export async function createPost(userId: number, input: CreatePostInput) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); return (await db.insert(posts).values({ userId, ...input, mediaUrl: input.mediaUrl ?? null, mediaName: input.mediaName ?? null, mediaMimeType: input.mediaMimeType ?? null }))[0].insertId; }
async function decoratePost(post: typeof posts.$inferSelect, viewerId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [author] = await db.select({ fullName: profiles.fullName, avatarUrl: profiles.avatarUrl, course: academicProfiles.course, classYear: academicProfiles.classYear, institution: academicProfiles.institution }).from(profiles).leftJoin(academicProfiles, eq(profiles.userId, academicProfiles.userId)).where(eq(profiles.userId, post.userId)).limit(1); const likes = await db.select().from(postLikes).where(eq(postLikes.postId, post.id)); const comments = await db.select().from(postComments).where(eq(postComments.postId, post.id)); const shares = await db.select().from(postShares).where(eq(postShares.postId, post.id)); const [liked] = await db.select().from(postLikes).where(and(eq(postLikes.postId, post.id), eq(postLikes.userId, viewerId))).limit(1); const [saved] = await db.select().from(postSaves).where(and(eq(postSaves.postId, post.id), eq(postSaves.userId, viewerId))).limit(1); return { ...post, author: author ?? { fullName: "Estudante Estuda+", avatarUrl: null, course: null, classYear: null, institution: null }, likeCount: likes.length, commentCount: comments.length, shareCount: shares.length, liked: Boolean(liked), saved: Boolean(saved) }; }
export async function getFeed(viewerId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); return Promise.all((await db.select().from(posts).where(eq(posts.moderationStatus, "visible")).orderBy(desc(posts.createdAt)).limit(50)).map((post) => decoratePost(post, viewerId))); }
export async function getPost(postId: number, viewerId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [post] = await db.select().from(posts).where(eq(posts.id, postId)).limit(1); return post ? decoratePost(post, viewerId) : null; }
export async function getPostComments(postId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); return db.select({ id: postComments.id, body: postComments.body, createdAt: postComments.createdAt, fullName: profiles.fullName, avatarUrl: profiles.avatarUrl }).from(postComments).leftJoin(profiles, eq(postComments.userId, profiles.userId)).where(eq(postComments.postId, postId)).orderBy(desc(postComments.createdAt)); }
export async function toggleLike(postId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [current] = await db.select().from(postLikes).where(and(eq(postLikes.postId, postId), eq(postLikes.userId, userId))).limit(1); if (current) { await db.delete(postLikes).where(eq(postLikes.id, current.id)); return false; } await db.insert(postLikes).values({ postId, userId }); return true; }
export async function toggleSave(postId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [current] = await db.select().from(postSaves).where(and(eq(postSaves.postId, postId), eq(postSaves.userId, userId))).limit(1); if (current) { await db.delete(postSaves).where(eq(postSaves.id, current.id)); return false; } await db.insert(postSaves).values({ postId, userId }); return true; }
export async function addComment(postId: number, userId: number, body: string) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); await db.insert(postComments).values({ postId, userId, body }); return getPostComments(postId); }
export async function sharePost(postId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); await db.insert(postShares).values({ postId, userId }); return (await db.select().from(postShares).where(eq(postShares.postId, postId))).length; }

export type CommunityInput = { name: string; description: string; category: string; educationLevel?: string | null; visibility: "public" | "private"; coverColor: string };
async function memberState(communityId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); return (await db.select().from(communityMembers).where(and(eq(communityMembers.communityId, communityId), eq(communityMembers.userId, userId))).limit(1))[0] ?? null; }
export async function listCommunities(userId: number, search = "", mineOnly = false) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const condition = search ? or(like(communities.name, `%${search}%`), like(communities.category, `%${search}%`)) : undefined; const rows = await db.select().from(communities).where(condition).orderBy(desc(communities.createdAt)); const result = await Promise.all(rows.map(async (community) => { const members = await db.select().from(communityMembers).where(eq(communityMembers.communityId, community.id)); const membership = members.find((member) => member.userId === userId); return { ...community, memberCount: members.length, isMember: Boolean(membership), memberRole: membership?.role ?? null }; })); return mineOnly ? result.filter((community) => community.isMember) : result; }
export async function createCommunity(userId: number, input: CommunityInput) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const communityId = (await db.insert(communities).values({ ownerUserId: userId, ...input, educationLevel: input.educationLevel ?? null }))[0].insertId; await db.insert(communityMembers).values({ communityId, userId, role: "admin" }); const conversationId = (await db.insert(conversations).values({ type: "community", title: `Conversa · ${input.name}`, communityId }))[0].insertId; await db.insert(conversationMembers).values({ conversationId, userId }); return { communityId, conversationId }; }
export async function getCommunity(communityId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [community] = await db.select().from(communities).where(eq(communities.id, communityId)).limit(1); if (!community) return null; const members = await db.select().from(communityMembers).where(eq(communityMembers.communityId, communityId)); const groups = await listStudyGroups(communityId, userId); const [conversation] = await db.select().from(conversations).where(eq(conversations.communityId, communityId)).limit(1); const membership = members.find((member) => member.userId === userId); return { ...community, memberCount: members.length, isMember: Boolean(membership), memberRole: membership?.role ?? null, conversationId: conversation?.id ?? null, groups }; }
export async function toggleCommunityMembership(communityId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [community] = await db.select().from(communities).where(eq(communities.id, communityId)).limit(1); if (!community) throw new Error("Comunidade não encontrada."); const existing = await memberState(communityId, userId); const [conversation] = await db.select().from(conversations).where(eq(conversations.communityId, communityId)).limit(1); if (existing) { if (existing.role === "admin") throw new Error("O administrador não pode sair da comunidade que criou."); await db.delete(communityMembers).where(eq(communityMembers.id, existing.id)); if (conversation) await db.delete(conversationMembers).where(and(eq(conversationMembers.conversationId, conversation.id), eq(conversationMembers.userId, userId))); return false; } await db.insert(communityMembers).values({ communityId, userId }); if (conversation) await db.insert(conversationMembers).values({ conversationId: conversation.id, userId }).onDuplicateKeyUpdate({ set: {} }); return true; }
export type StudyGroupInput = { communityId: number; name: string; description: string; privacy: "public" | "private" };
export async function listStudyGroups(communityId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const rows = await db.select().from(studyGroups).where(eq(studyGroups.communityId, communityId)).orderBy(desc(studyGroups.createdAt)); return Promise.all(rows.map(async (group) => { const members = await db.select().from(studyGroupMembers).where(eq(studyGroupMembers.groupId, group.id)); return { ...group, memberCount: members.length, isMember: members.some((item) => item.userId === userId) }; })); }
export async function createStudyGroup(userId: number, input: StudyGroupInput) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const membership = await memberState(input.communityId, userId); if (!membership) throw new Error("Entre na comunidade antes de criar um grupo de estudo."); const groupId = (await db.insert(studyGroups).values({ ownerUserId: userId, ...input }))[0].insertId; await db.insert(studyGroupMembers).values({ groupId, userId, role: "admin" }); const conversationId = (await db.insert(conversations).values({ type: "group", title: input.name, studyGroupId: groupId }))[0].insertId; await db.update(studyGroups).set({ conversationId }).where(eq(studyGroups.id, groupId)); await db.insert(conversationMembers).values({ conversationId, userId }); return { groupId, conversationId }; }
export async function getStudyGroup(groupId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [group] = await db.select().from(studyGroups).where(eq(studyGroups.id, groupId)).limit(1); if (!group) return null; const members = await db.select().from(studyGroupMembers).where(eq(studyGroupMembers.groupId, groupId)); return { ...group, memberCount: members.length, isMember: members.some((item) => item.userId === userId) }; }
export async function toggleStudyGroupMembership(groupId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [group] = await db.select().from(studyGroups).where(eq(studyGroups.id, groupId)).limit(1); if (!group) throw new Error("Grupo não encontrado."); const [existing] = await db.select().from(studyGroupMembers).where(and(eq(studyGroupMembers.groupId, groupId), eq(studyGroupMembers.userId, userId))).limit(1); if (existing) { if (existing.role === "admin") throw new Error("O administrador não pode sair do grupo que criou."); await db.delete(studyGroupMembers).where(eq(studyGroupMembers.id, existing.id)); if (group.conversationId) await db.delete(conversationMembers).where(and(eq(conversationMembers.conversationId, group.conversationId), eq(conversationMembers.userId, userId))); return false; } await db.insert(studyGroupMembers).values({ groupId, userId }); if (group.conversationId) await db.insert(conversationMembers).values({ conversationId: group.conversationId, userId }).onDuplicateKeyUpdate({ set: {} }); return true; }
export async function studentDirectory(userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); return db.select({ userId: profiles.userId, fullName: profiles.fullName, avatarUrl: profiles.avatarUrl, course: academicProfiles.course, classYear: academicProfiles.classYear }).from(profiles).leftJoin(academicProfiles, eq(profiles.userId, academicProfiles.userId)).where(ne(profiles.userId, userId)).limit(50); }
export async function startDirectConversation(userId: number, recipientId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); if (userId === recipientId) throw new Error("Seleccione outro estudante."); const own = await db.select().from(conversationMembers).where(eq(conversationMembers.userId, userId)); for (const membership of own) { const [conversation] = await db.select().from(conversations).where(and(eq(conversations.id, membership.conversationId), eq(conversations.type, "direct"))).limit(1); if (conversation) { const [recipient] = await db.select().from(conversationMembers).where(and(eq(conversationMembers.conversationId, conversation.id), eq(conversationMembers.userId, recipientId))).limit(1); if (recipient) return conversation.id; } } const conversationId = (await db.insert(conversations).values({ type: "direct" }))[0].insertId; await db.insert(conversationMembers).values([{ conversationId, userId }, { conversationId, userId: recipientId }]); return conversationId; }
export async function listConversations(userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const memberships = await db.select().from(conversationMembers).where(eq(conversationMembers.userId, userId)); return Promise.all(memberships.map(async (membership) => { const [conversation] = await db.select().from(conversations).where(eq(conversations.id, membership.conversationId)).limit(1); if (!conversation) return null; const [last] = await db.select().from(messages).where(eq(messages.conversationId, conversation.id)).orderBy(desc(messages.createdAt)).limit(1); let title = conversation.title || "Conversa"; let avatarUrl: string | null = null; if (conversation.type === "direct") { const members = await db.select().from(conversationMembers).where(and(eq(conversationMembers.conversationId, conversation.id), ne(conversationMembers.userId, userId))).limit(1); if (members[0]) { const [person] = await db.select({ fullName: profiles.fullName, avatarUrl: profiles.avatarUrl }).from(profiles).where(eq(profiles.userId, members[0].userId)).limit(1); title = person?.fullName || "Estudante"; avatarUrl = person?.avatarUrl ?? null; } } return { ...conversation, title, avatarUrl, lastMessage: last?.body ?? "Ainda não há mensagens.", lastMessageAt: last?.createdAt ?? conversation.createdAt }; })).then((items) => items.filter(Boolean).sort((a: any, b: any) => Number(new Date(b.lastMessageAt)) - Number(new Date(a.lastMessageAt)))); }
async function requireConversationMember(conversationId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [member] = await db.select().from(conversationMembers).where(and(eq(conversationMembers.conversationId, conversationId), eq(conversationMembers.userId, userId))).limit(1); if (!member) throw new Error("Não tem acesso a esta conversa."); }
export async function getMessages(conversationId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); await requireConversationMember(conversationId, userId); const [conversation] = await db.select().from(conversations).where(eq(conversations.id, conversationId)).limit(1); const rows = await db.select({ id: messages.id, senderUserId: messages.senderUserId, body: messages.body, createdAt: messages.createdAt, fullName: profiles.fullName, avatarUrl: profiles.avatarUrl }).from(messages).leftJoin(profiles, eq(messages.senderUserId, profiles.userId)).where(eq(messages.conversationId, conversationId)).orderBy(messages.createdAt); return { conversation, messages: rows }; }
export async function sendMessage(conversationId: number, userId: number, body: string) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); await requireConversationMember(conversationId, userId); await db.insert(messages).values({ conversationId, senderUserId: userId, body }); await db.update(conversations).set({ updatedAt: new Date() }).where(eq(conversations.id, conversationId)); return getMessages(conversationId, userId); }

export type LearningResourceInput = { type: "book" | "material" | "video"; title: string; description: string; subject: string; educationLevel?: string | null; author: string; coverColor: string; fileUrl?: string | null; fileName?: string | null; mimeType?: string | null; durationSeconds?: number; access: "public" | "community" | "group"; communityId?: number | null; studyGroupId?: number | null };
async function hasResourceAccess(resource: typeof learningResources.$inferSelect, userId: number) { const db = await getDb(); if (!db) return false; if (resource.ownerUserId === userId || resource.access === "public") return true; if (resource.access === "group" && resource.studyGroupId) { const [member] = await db.select().from(studyGroupMembers).where(and(eq(studyGroupMembers.groupId, resource.studyGroupId), eq(studyGroupMembers.userId, userId))).limit(1); return Boolean(member); } if (resource.access === "community" && resource.communityId) return Boolean(await memberState(resource.communityId, userId)); return false; }
export async function createLearningResource(userId: number, input: LearningResourceInput) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); if (input.access === "group") { if (!input.studyGroupId) throw new Error("Seleccione o grupo de estudo que poderá aceder ao material."); const [membership] = await db.select().from(studyGroupMembers).where(and(eq(studyGroupMembers.groupId, input.studyGroupId), eq(studyGroupMembers.userId, userId))).limit(1); if (!membership) throw new Error("Só pode publicar materiais nos grupos em que participa."); } if (input.access === "community") { if (!input.communityId || !(await memberState(input.communityId, userId))) throw new Error("Só pode publicar materiais nas comunidades em que participa."); } return (await db.insert(learningResources).values({ ownerUserId: userId, ...input, educationLevel: input.educationLevel ?? null, fileUrl: input.fileUrl ?? null, fileName: input.fileName ?? null, mimeType: input.mimeType ?? null, durationSeconds: input.durationSeconds ?? 0, communityId: input.communityId ?? null, studyGroupId: input.studyGroupId ?? null }))[0].insertId; }
export async function listLearningResources(userId: number, filters: { search?: string; type?: "book" | "material" | "video"; subject?: string; savedOnly?: boolean; communityId?: number; studyGroupId?: number } = {}) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); let rows = await db.select().from(learningResources).orderBy(desc(learningResources.createdAt)); if (filters.studyGroupId) rows = rows.filter((item) => item.studyGroupId === filters.studyGroupId); if (filters.communityId) rows = rows.filter((item) => item.communityId === filters.communityId); if (filters.type) rows = rows.filter((item) => item.type === filters.type); if (filters.subject) rows = rows.filter((item) => item.subject === filters.subject); if (filters.search) { const value = filters.search.toLowerCase(); rows = rows.filter((item) => `${item.title} ${item.description} ${item.subject}`.toLowerCase().includes(value)); } const decorated = await Promise.all(rows.map(async (resource) => { const allowed = await hasResourceAccess(resource, userId); if (!allowed) return null; const [owner] = await db.select({ fullName: profiles.fullName }).from(profiles).where(eq(profiles.userId, resource.ownerUserId)).limit(1); const [saved] = await db.select().from(resourceSaves).where(and(eq(resourceSaves.resourceId, resource.id), eq(resourceSaves.userId, userId))).limit(1); const [progress] = await db.select().from(resourceProgress).where(and(eq(resourceProgress.resourceId, resource.id), eq(resourceProgress.userId, userId))).limit(1); return { ...resource, ownerName: owner?.fullName ?? resource.author, saved: Boolean(saved), watchedSeconds: progress?.watchedSeconds ?? 0, completed: progress?.completed ?? false }; })); return decorated.filter(Boolean).filter((item: any) => !filters.savedOnly || item.saved); }
export async function getLearningResource(resourceId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [resource] = await db.select().from(learningResources).where(eq(learningResources.id, resourceId)).limit(1); if (!resource || !(await hasResourceAccess(resource, userId))) return null; return (await listLearningResources(userId)).find((item: any) => item.id === resourceId) ?? null; }
export async function toggleResourceSave(resourceId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const resource = await getLearningResource(resourceId, userId); if (!resource) throw new Error("Recurso não encontrado ou sem acesso."); const [existing] = await db.select().from(resourceSaves).where(and(eq(resourceSaves.resourceId, resourceId), eq(resourceSaves.userId, userId))).limit(1); if (existing) { await db.delete(resourceSaves).where(eq(resourceSaves.id, existing.id)); return false; } await db.insert(resourceSaves).values({ resourceId, userId }); return true; }
export async function updateResourceProgress(resourceId: number, userId: number, watchedSeconds: number, completed: boolean) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const resource = await getLearningResource(resourceId, userId); if (!resource || resource.type !== "video") throw new Error("Videoaula não encontrada ou sem acesso."); const safeSeconds = Math.max(0, Math.min(Math.floor(watchedSeconds), resource.durationSeconds || Math.floor(watchedSeconds))); await db.insert(resourceProgress).values({ resourceId, userId, watchedSeconds: safeSeconds, completed }).onDuplicateKeyUpdate({ set: { watchedSeconds: safeSeconds, completed } }); return { watchedSeconds: safeSeconds, completed }; }

export async function getTeacherSession(userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); let [session] = await db.select().from(teacherSessions).where(eq(teacherSessions.userId, userId)).limit(1); if (!session) { const id = (await db.insert(teacherSessions).values({ userId }))[0].insertId; [session] = await db.select().from(teacherSessions).where(eq(teacherSessions.id, id)).limit(1); } return session; }
export async function listTeacherMessages(userId: number, limit = 30) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const session = await getTeacherSession(userId); const rows = await db.select().from(teacherMessages).where(eq(teacherMessages.sessionId, session.id)).orderBy(desc(teacherMessages.createdAt)).limit(limit); return { session, messages: rows.reverse() }; }
export async function addTeacherMessage(userId: number, role: "user" | "assistant", action: "explain" | "solve" | "summary" | "quiz" | "plan" | "general", content: string) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const session = await getTeacherSession(userId); await db.insert(teacherMessages).values({ sessionId: session.id, role, action, content }); await db.update(teacherSessions).set({ updatedAt: new Date() }).where(eq(teacherSessions.id, session.id)); return session; }
export async function getTeacherContext(userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const profile = await getStudentProfile(userId); const savedResources = await listLearningResources(userId, { savedOnly: true }); return { profile, savedResources: savedResources.slice(0, 5).map((item: any) => ({ title: item.title, subject: item.subject, type: item.type })) }; }
export async function listStudyPlans(userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); return db.select().from(studyPlans).where(eq(studyPlans.userId, userId)).orderBy(desc(studyPlans.createdAt)); }
export async function saveStudyPlan(userId: number, input: { subject: string; goal: string; title: string; planJson: string }) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); await db.update(studyPlans).set({ isActive: false }).where(eq(studyPlans.userId, userId)); const id = (await db.insert(studyPlans).values({ userId, ...input }))[0].insertId; return (await db.select().from(studyPlans).where(eq(studyPlans.id, id)).limit(1))[0]; }

export type CompetitionInput = { title: string; description: string; subject: string; educationLevel?: string | null; format: "individual" | "group"; startAt: Date; endAt: Date; registrationDeadline: Date; capacity: number; reward?: string | null; communityId?: number | null; studyGroupId?: number | null; coverColor: string };
async function hasCompetitionAccess(competition: typeof competitions.$inferSelect, userId: number) { const db = await getDb(); if (!db) return false; if (competition.ownerUserId === userId) return true; if (competition.studyGroupId) { const [member] = await db.select().from(studyGroupMembers).where(and(eq(studyGroupMembers.groupId, competition.studyGroupId), eq(studyGroupMembers.userId, userId))).limit(1); return Boolean(member); } if (competition.communityId) return Boolean(await memberState(competition.communityId, userId)); return true; }
export async function createCompetition(userId: number, input: CompetitionInput) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); if (input.studyGroupId) { const [member] = await db.select().from(studyGroupMembers).where(and(eq(studyGroupMembers.groupId, input.studyGroupId), eq(studyGroupMembers.userId, userId))).limit(1); if (!member) throw new Error("Só podes criar uma competição no teu grupo de estudo."); } else if (input.communityId && !(await memberState(input.communityId, userId))) throw new Error("Só podes criar uma competição numa comunidade em que participas."); const id = (await db.insert(competitions).values({ ownerUserId: userId, ...input, educationLevel: input.educationLevel ?? null, reward: input.reward ?? null, communityId: input.communityId ?? null, studyGroupId: input.studyGroupId ?? null }))[0].insertId; return id; }
async function decorateCompetition(competition: typeof competitions.$inferSelect, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const enrollments = await db.select().from(competitionEnrollments).where(and(eq(competitionEnrollments.competitionId, competition.id), eq(competitionEnrollments.status, "registered"))); const [mine] = await db.select().from(competitionEnrollments).where(and(eq(competitionEnrollments.competitionId, competition.id), eq(competitionEnrollments.userId, userId))).limit(1); const [owner] = await db.select({ fullName: profiles.fullName }).from(profiles).where(eq(profiles.userId, competition.ownerUserId)).limit(1); const now = new Date(); const isOpen = competition.status === "open" && now <= competition.registrationDeadline && enrollments.length < competition.capacity; return { ...competition, ownerName: owner?.fullName ?? "Organização Estuda+", enrollmentCount: enrollments.length, enrollmentStatus: mine?.status ?? null, isOpen, isOwner: competition.ownerUserId === userId }; }
export async function listCompetitions(userId: number, filters: { search?: string; subject?: string; mineOnly?: boolean } = {}) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); let rows = await db.select().from(competitions).orderBy(desc(competitions.createdAt)); if (filters.subject) rows = rows.filter((item) => item.subject === filters.subject); if (filters.search) { const query = filters.search.toLowerCase(); rows = rows.filter((item) => `${item.title} ${item.description} ${item.subject}`.toLowerCase().includes(query)); } const allowed = await Promise.all(rows.map(async (item) => (await hasCompetitionAccess(item, userId)) ? decorateCompetition(item, userId) : null)); return allowed.filter(Boolean).filter((item: any) => !filters.mineOnly || item.enrollmentStatus === "registered" || item.isOwner); }
export async function getCompetition(competitionId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [competition] = await db.select().from(competitions).where(eq(competitions.id, competitionId)).limit(1); if (!competition || !(await hasCompetitionAccess(competition, userId))) return null; return decorateCompetition(competition, userId); }
export async function toggleCompetitionEnrollment(competitionId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const competition = await getCompetition(competitionId, userId); if (!competition) throw new Error("Competição não encontrada ou sem acesso."); if (competition.isOwner) throw new Error("O organizador já acompanha esta competição."); const [existing] = await db.select().from(competitionEnrollments).where(and(eq(competitionEnrollments.competitionId, competitionId), eq(competitionEnrollments.userId, userId))).limit(1); if (existing?.status === "registered") { await db.update(competitionEnrollments).set({ status: "withdrawn" }).where(eq(competitionEnrollments.id, existing.id)); return "withdrawn" as const; } if (!competition.isOpen) throw new Error("As inscrições não estão abertas para esta competição."); if (existing) await db.update(competitionEnrollments).set({ status: "registered" }).where(eq(competitionEnrollments.id, existing.id)); else await db.insert(competitionEnrollments).values({ competitionId, userId }); return "registered" as const; }
async function createNotification(userId: number, type: "competition" | "submission" | "evaluation" | "certificate" | "system", title: string, body: string, targetPath?: string | null) { const db = await getDb(); if (!db) return; await db.insert(notifications).values({ userId, type, title, body, targetPath: targetPath ?? null }); }
async function awardBadge(userId: number, type: "participant" | "reviewed" | "excellence") { const db = await getDb(); if (!db) return; const catalog = { participant: { title: "Primeira participação", description: "Enviou uma resposta numa competição académica.", icon: "emoji-events" }, reviewed: { title: "Resposta avaliada", description: "Recebeu uma avaliação construtiva numa competição.", icon: "verified" }, excellence: { title: "Excelência académica", description: "Alcançou uma pontuação de 90 ou mais numa competição.", icon: "workspace-premium" } } as const; await db.insert(studentBadges).values({ userId, type, ...catalog[type] }).onDuplicateKeyUpdate({ set: {} }); }
export async function listNotifications(userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const rows = await db.select().from(notifications).where(eq(notifications.userId, userId)).orderBy(desc(notifications.createdAt)).limit(80); return { items: rows, unreadCount: rows.filter((item) => !item.readAt).length }; }
export async function markNotificationRead(notificationId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); await db.update(notifications).set({ readAt: new Date() }).where(and(eq(notifications.id, notificationId), eq(notifications.userId, userId))); return true; }
