export async function listOwnerSafetyReports(status?: "submitted" | "reviewing" | "resolved" | "dismissed") { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); return db.select({ id: safetyReports.id, reporterUserId: safetyReports.reporterUserId, targetType: safetyReports.targetType, targetId: safetyReports.targetId, category: safetyReports.category, details: safetyReports.details, status: safetyReports.status, resolutionNote: safetyReports.resolutionNote, createdAt: safetyReports.createdAt, reviewerUserId: safetyReports.reviewerUserId, reporterName: profiles.fullName }).from(safetyReports).leftJoin(profiles, eq(safetyReports.reporterUserId, profiles.userId)).where(status ? eq(safetyReports.status, status) : undefined).orderBy(desc(safetyReports.createdAt)).limit(100); }
export async function resolveSafetyReport(reviewerUserId: number, reportId: number, status: "reviewing" | "resolved" | "dismissed", resolutionNote: string) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [report] = await db.select().from(safetyReports).where(eq(safetyReports.id, reportId)).limit(1); if (!report) throw new Error("Denúncia não encontrada."); await db.update(safetyReports).set({ status, reviewerUserId, resolutionNote, reviewedAt: new Date() }).where(eq(safetyReports.id, reportId)); await db.insert(ownerAuditLogs).values({ actorUserId: reviewerUserId, targetUserId: report.reporterUserId, targetType: "user", targetId: report.targetId, action: `report_${status}`, reason: resolutionNote }); return { success: true }; }
export async function getSubjectProgress(userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const allowed = await listLearningResources(userId); const resources = allowed as { id: number; subject: string; type: string; watchedSeconds: number; completed: boolean }[]; const submissions = await db.select({ competitionId: competitionSubmissions.competitionId, score: competitionSubmissions.score, subject: competitions.subject }).from(competitionSubmissions).leftJoin(competitions, eq(competitionSubmissions.competitionId, competitions.id)).where(and(eq(competitionSubmissions.userId, userId), eq(competitionSubmissions.status, "reviewed")));
  const subjects = new Map<string, { subject: string; resources: number; completed: number; watchedMinutes: number; scores: number[] }>();
  for (const resource of resources) { const item = subjects.get(resource.subject) ?? { subject: resource.subject, resources: 0, completed: 0, watchedMinutes: 0, scores: [] }; item.resources += 1; item.completed += resource.completed ? 1 : 0; item.watchedMinutes += Math.floor(resource.watchedSeconds / 60); subjects.set(resource.subject, item); }
  for (const submission of submissions) { const subject = submission.subject ?? "Geral"; const item = subjects.get(subject) ?? { subject, resources: 0, completed: 0, watchedMinutes: 0, scores: [] }; if (submission.score !== null) item.scores.push(submission.score); subjects.set(subject, item); }
  return [...subjects.values()].map((item) => ({ subject: item.subject, resources: item.resources, completed: item.completed, watchedMinutes: item.watchedMinutes, averageScore: item.scores.length ? Math.round(item.scores.reduce((sum, score) => sum + score, 0) / item.scores.length) : null, completionRate: item.resources ? Math.round((item.completed / item.resources) * 100) : 0 })).sort((a, b) => b.watchedMinutes - a.watchedMinutes || b.resources - a.resources);
}
