export async function getStudentAchievements(userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const badges = await db.select().from(studentBadges).where(eq(studentBadges.userId, userId)).orderBy(desc(studentBadges.awardedAt)); const certificates = await db.select({ id: competitionCertificates.id, score: competitionCertificates.score, issuedAt: competitionCertificates.issuedAt, certificateCode: competitionCertificates.certificateCode, competitionTitle: competitions.title, coverColor: competitions.coverColor }).from(competitionCertificates).leftJoin(competitions, eq(competitionCertificates.competitionId, competitions.id)).where(eq(competitionCertificates.userId, userId)).orderBy(desc(competitionCertificates.issuedAt)); const weekly = await db.select({ id: weeklyChallengeAwards.id, title: weeklyChallengeAwards.title, awardedAt: weeklyChallengeAwards.awardedAt, expiresAt: weeklyChallengeAwards.expiresAt, challengeTitle: weeklyChallenges.title, coverColor: weeklyChallenges.coverColor }).from(weeklyChallengeAwards).leftJoin(weeklyChallenges, eq(weeklyChallengeAwards.challengeId, weeklyChallenges.id)).where(and(eq(weeklyChallengeAwards.userId, userId), gt(weeklyChallengeAwards.expiresAt, new Date()))).orderBy(desc(weeklyChallengeAwards.awardedAt)); return { badges, certificates, weekly }; }
async function requireCompetitionParticipant(competitionId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const competition = await getCompetition(competitionId, userId); if (!competition) throw new Error("Competição não encontrada ou sem acesso."); const [enrollment] = await db.select().from(competitionEnrollments).where(and(eq(competitionEnrollments.competitionId, competitionId), eq(competitionEnrollments.userId, userId), eq(competitionEnrollments.status, "registered"))).limit(1); if (!enrollment) throw new Error("Inscreve-te na competição antes de enviar a resposta."); return competition; }
export async function getCompetitionParticipation(competitionId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const competition = await getCompetition(competitionId, userId); if (!competition) return null; const [submission] = await db.select().from(competitionSubmissions).where(and(eq(competitionSubmissions.competitionId, competitionId), eq(competitionSubmissions.userId, userId))).limit(1); const [certificate] = await db.select().from(competitionCertificates).where(and(eq(competitionCertificates.competitionId, competitionId), eq(competitionCertificates.userId, userId))).limit(1); const attachments = submission ? await db.select().from(competitionSubmissionAttachments).where(eq(competitionSubmissionAttachments.submissionId, submission.id)).orderBy(desc(competitionSubmissionAttachments.createdAt)) : []; return { competition, submission: submission ?? null, certificate: certificate ?? null, attachments }; }
export async function submitCompetitionResponse(competitionId: number, userId: number, response: string) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const competition = await requireCompetitionParticipant(competitionId, userId); if (new Date() > competition.endAt) throw new Error("O período de submissão desta competição terminou."); const [existing] = await db.select().from(competitionSubmissions).where(and(eq(competitionSubmissions.competitionId, competitionId), eq(competitionSubmissions.userId, userId))).limit(1); if (existing?.status === "reviewed") throw new Error("Esta resposta já foi avaliada e não pode ser alterada."); if (existing) await db.update(competitionSubmissions).set({ response, status: "submitted", score: null, feedback: null, submittedAt: new Date() }).where(eq(competitionSubmissions.id, existing.id)); else { await db.insert(competitionSubmissions).values({ competitionId, userId, response }); await createNotification(competition.ownerUserId, "submission", "Nova submissão recebida", `Um participante enviou uma resposta para “${competition.title}”.`, `/competitions/${competitionId}/manage`); await awardBadge(userId, "participant"); } return getCompetitionParticipation(competitionId, userId); }
export async function addCompetitionSubmissionAttachment(competitionId: number, userId: number, attachment: { fileUrl: string; fileName: string; mimeType: string; fileSize: number }) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const participation = await getCompetitionParticipation(competitionId, userId); if (!participation?.submission) throw new Error("Envia primeiro a resposta antes de adicionar anexos."); if (participation.submission.status === "reviewed") throw new Error("A resposta já foi avaliada e não pode receber novos anexos."); await db.insert(competitionSubmissionAttachments).values({ submissionId: participation.submission.id, uploadedByUserId: userId, ...attachment }); return getCompetitionParticipation(competitionId, userId); }
export async function listCompetitionSubmissions(competitionId: number, requesterId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const competition = await getCompetition(competitionId, requesterId); if (!competition || !competition.isOwner) throw new Error("Só o organizador pode consultar as submissões."); const rows = await db.select({ id: competitionSubmissions.id, userId: competitionSubmissions.userId, response: competitionSubmissions.response, status: competitionSubmissions.status, score: competitionSubmissions.score, feedback: competitionSubmissions.feedback, submittedAt: competitionSubmissions.submittedAt, fullName: profiles.fullName, avatarUrl: profiles.avatarUrl }).from(competitionSubmissions).leftJoin(profiles, eq(competitionSubmissions.userId, profiles.userId)).where(eq(competitionSubmissions.competitionId, competitionId)).orderBy(desc(competitionSubmissions.submittedAt)); return rows; }
export async function reviewCompetitionSubmission(submissionId: number, requesterId: number, score: number, feedback: string) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [submission] = await db.select().from(competitionSubmissions).where(eq(competitionSubmissions.id, submissionId)).limit(1); if (!submission) throw new Error("Submissão não encontrada."); const competition = await getCompetition(submission.competitionId, requesterId); if (!competition || !competition.isOwner) throw new Error("Só o organizador pode avaliar esta resposta."); await db.update(competitionSubmissions).set({ status: "reviewed", score, feedback }).where(eq(competitionSubmissions.id, submissionId)); const code = `ESTU-${competition.id}-${submission.userId}-${submission.id}`; await db.insert(competitionCertificates).values({ competitionId: competition.id, userId: submission.userId, submissionId: submission.id, certificateCode: code, score }).onDuplicateKeyUpdate({ set: { submissionId: submission.id, score, issuedAt: new Date() } }); await createNotification(submission.userId, "evaluation", "A tua resposta foi avaliada", `Recebeste ${score}/100 em “${competition.title}”.`, `/competitions/${competition.id}`); await createNotification(submission.userId, "certificate", "Certificado digital emitido", `O teu certificado de “${competition.title}” já está disponível.`, `/competitions/${competition.id}`); await awardBadge(submission.userId, "reviewed"); if (score >= 90) await awardBadge(submission.userId, "excellence"); return { submissionId, competitionId: competition.id, certificateCode: code }; }
export async function getCompetitionLeaderboard(competitionId: number, requesterId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const competition = await getCompetition(competitionId, requesterId); if (!competition) throw new Error("Competição não encontrada ou sem acesso."); const rows = await db.select({ userId: competitionSubmissions.userId, fullName: profiles.fullName, avatarUrl: profiles.avatarUrl, score: competitionSubmissions.score, submittedAt: competitionSubmissions.submittedAt }).from(competitionSubmissions).leftJoin(profiles, eq(competitionSubmissions.userId, profiles.userId)).where(and(eq(competitionSubmissions.competitionId, competitionId), eq(competitionSubmissions.status, "reviewed"))).orderBy(desc(competitionSubmissions.score), competitionSubmissions.submittedAt); return rows.map((row, index) => ({ ...row, rank: index + 1 })); }
export async function getCompetitionCertificate(certificateId: number, requesterId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [certificate] = await db.select().from(competitionCertificates).where(eq(competitionCertificates.id, certificateId)).limit(1); if (!certificate) return null; const competition = await getCompetition(certificate.competitionId, requesterId); if (!competition || (certificate.userId !== requesterId && !competition.isOwner)) throw new Error("Não tem acesso a este certificado."); const [recipient] = await db.select({ fullName: profiles.fullName, course: academicProfiles.course, classYear: academicProfiles.classYear }).from(profiles).leftJoin(academicProfiles, eq(profiles.userId, academicProfiles.userId)).where(eq(profiles.userId, certificate.userId)).limit(1); return { ...certificate, competition, recipient: recipient ?? { fullName: "Estudante Estuda+", course: null, classYear: null } }; }
export async function verifyCertificateByCode(certificateCode: string) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [certificate] = await db.select().from(competitionCertificates).where(eq(competitionCertificates.certificateCode, certificateCode.trim().toUpperCase())).limit(1); if (!certificate) return { valid: false as const }; const [competition] = await db.select({ title: competitions.title, subject: competitions.subject }).from(competitions).where(eq(competitions.id, certificate.competitionId)).limit(1); const [recipient] = await db.select({ fullName: profiles.fullName }).from(profiles).where(eq(profiles.userId, certificate.userId)).limit(1); return { valid: true as const, certificateCode: certificate.certificateCode, score: certificate.score, issuedAt: certificate.issuedAt, competitionTitle: competition?.title ?? "Competição Estuda+", subject: competition?.subject ?? null, recipientName: recipient?.fullName ?? "Estudante Estuda+" }; }
export async function getDeviceNotificationSettings(userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [settings] = await db.select().from(deviceNotificationSettings).where(eq(deviceNotificationSettings.userId, userId)).limit(1); return settings ?? { userId, deviceEnabled: false, dailyReminderEnabled: false, reminderHour: 18, expoPushToken: null, tokenUpdatedAt: null }; }
export async function saveDeviceNotificationSettings(userId: number, input: { deviceEnabled: boolean; dailyReminderEnabled: boolean; reminderHour: number }) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const reminderHour = Math.max(6, Math.min(22, Math.floor(input.reminderHour))); await db.insert(deviceNotificationSettings).values({ userId, ...input, reminderHour }).onDuplicateKeyUpdate({ set: { deviceEnabled: input.deviceEnabled, dailyReminderEnabled: input.dailyReminderEnabled, reminderHour } }); return getDeviceNotificationSettings(userId); }
export async function registerDevicePushToken(userId: number, token: string | null) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); await db.insert(deviceNotificationSettings).values({ userId, expoPushToken: token, tokenUpdatedAt: token ? new Date() : null }).onDuplicateKeyUpdate({ set: { expoPushToken: token, tokenUpdatedAt: token ? new Date() : null } }); return getDeviceNotificationSettings(userId); }
export type WeeklyChallengeInput = { weekCode: string; title: string; description: string; subject: string; startAt: Date; endAt: Date; coverColor: string; badgeTitle: string };
async function decorateWeeklyChallenge(challenge: typeof weeklyChallenges.$inferSelect, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const participants = await db.select().from(weeklyChallengeParticipants).where(and(eq(weeklyChallengeParticipants.challengeId, challenge.id), ne(weeklyChallengeParticipants.status, "withdrawn"))); const [mine] = await db.select().from(weeklyChallengeParticipants).where(and(eq(weeklyChallengeParticipants.challengeId, challenge.id), eq(weeklyChallengeParticipants.userId, userId))).limit(1); return { ...challenge, participantCount: participants.length, participationStatus: mine?.status ?? null, isOwner: challenge.ownerUserId === userId, isActive: new Date() <= challenge.endAt }; }
export async function listWeeklyChallenges(userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const rows = await db.select().from(weeklyChallenges).orderBy(desc(weeklyChallenges.startAt)); return Promise.all(rows.map((challenge) => decorateWeeklyChallenge(challenge, userId))); }
export async function getWeeklyChallenge(challengeId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const [challenge] = await db.select().from(weeklyChallenges).where(eq(weeklyChallenges.id, challengeId)).limit(1); return challenge ? decorateWeeklyChallenge(challenge, userId) : null; }
export async function createWeeklyChallenge(userId: number, input: WeeklyChallengeInput) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); if (input.endAt <= input.startAt) throw new Error("A data de fim deve ser posterior ao início."); return (await db.insert(weeklyChallenges).values({ ownerUserId: userId, ...input }))[0].insertId; }
export async function toggleWeeklyChallengeParticipation(challengeId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const challenge = await getWeeklyChallenge(challengeId, userId); if (!challenge) throw new Error("Desafio semanal não encontrado."); if (challenge.isOwner) throw new Error("O organizador já acompanha este desafio."); const [current] = await db.select().from(weeklyChallengeParticipants).where(and(eq(weeklyChallengeParticipants.challengeId, challengeId), eq(weeklyChallengeParticipants.userId, userId))).limit(1); if (current?.status === "joined") { await db.update(weeklyChallengeParticipants).set({ status: "withdrawn" }).where(eq(weeklyChallengeParticipants.id, current.id)); return "withdrawn" as const; } if (!challenge.isActive) throw new Error("Este desafio semanal já terminou."); if (current) await db.update(weeklyChallengeParticipants).set({ status: "joined", completedAt: null }).where(eq(weeklyChallengeParticipants.id, current.id)); else await db.insert(weeklyChallengeParticipants).values({ challengeId, userId }); await createNotification(userId, "system", "Inscrição confirmada", `Entraste no desafio semanal “${challenge.title}”.`, `/challenges/${challenge.id}`); return "joined" as const; }
export async function completeWeeklyChallenge(challengeId: number, userId: number) { const db = await getDb(); if (!db) throw new Error("Base de dados indisponível."); const challenge = await getWeeklyChallenge(challengeId, userId); if (!challenge?.isActive) throw new Error("Este desafio semanal não está disponível."); const [participant] = await db.select().from(weeklyChallengeParticipants).where(and(eq(weeklyChallengeParticipants.challengeId, challengeId), eq(weeklyChallengeParticipants.userId, userId), eq(weeklyChallengeParticipants.status, "joined"))).limit(1); if (!participant) throw new Error("Entra no desafio antes de o concluir."); await db.update(weeklyChallengeParticipants).set({ status: "completed", completedAt: new Date() }).where(eq(weeklyChallengeParticipants.id, participant.id)); const expiresAt = new Date(challenge.endAt); expiresAt.setDate(expiresAt.getDate() + 7); await db.insert(weeklyChallengeAwards).values({ challengeId, userId, title: challenge.badgeTitle, expiresAt }).onDuplicateKeyUpdate({ set: { expiresAt, awardedAt: new Date() } }); await createNotification(userId, "system", "Medalha semanal conquistada", `Concluíste “${challenge.title}” e recebeste a medalha “${challenge.badgeTitle}”.`, `/challenges/${challenge.id}`); return getWeeklyChallenge(challengeId, userId); }
